INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die statische Sicht des PSP eine hierarchische Darstellung?', 2, '[{"text": "Ja", "correct": true, "because": "Zeigt feste Struktur"}, {"text": "Nein", "correct": false, "because": "Sie ist hierarchisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der statischen Sicht im PSP?', 3, '[{"text": "Projekt in feste Teilbereiche gliedern", "correct": true, "because": "Fördert Übersicht"}, {"text": "Zeitliche Abläufe festlegen", "correct": false, "because": "Dynamische Sicht"}, {"text": "Team direkt koordinieren", "correct": false, "because": "Durchführungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die statische Sicht enthält Arbeitspakete. b) Sie zeigt den Projektfortschritt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, keine Zeit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile zeigt die statische Sicht des PSP?', 4, '[{"text": "Projektphasen", "correct": true, "because": "Oberste Struktur"}, {"text": "Unklare Aufgaben", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Teilprojekte", "correct": true, "because": "Mittlere Ebene"}, {"text": "Arbeitspakete", "correct": true, "because": "Detaillierte Einheiten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die statische Sicht zeitliche Abhängigkeiten darstellen?', 2, '[{"text": "Nein", "correct": true, "because": "Fokussiert Struktur, nicht Zeit"}, {"text": "Ja", "correct": false, "because": "Dynamische Sicht nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel gehört zur statischen Sicht?', 3, '[{"text": "1.1.2 Softwareentwicklung", "correct": true, "because": "Hierarchisch ohne Zeit"}, {"text": "Entwicklung bis 30. Juni", "correct": false, "because": "Zeitangabe enthalten"}, {"text": "Irgendwas entwickeln", "correct": false, "because": "Nicht strukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die statische Sicht nur für komplexe Projekte geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch einfache Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Universelle Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat die statische Sicht im PSP?', 3, '[{"text": "Projektorganisation klar darstellen", "correct": true, "because": "Fördert Verständnis"}, {"text": "Fortschritt direkt messen", "correct": false, "because": "Dynamische Sicht"}, {"text": "Ressourcen direkt zuweisen", "correct": false, "because": "Durchführungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die statische Sicht ist zeitunabhängig. b) Sie enthält nur Hauptphasen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne statische Sicht im PSP?', 3, '[{"text": "Projektstruktur bleibt unklar", "correct": true, "because": "Fehlende Gliederung"}, {"text": "Zeitplan wird einfacher", "correct": false, "because": "Eher Verwirrung"}, {"text": "Kosten sinken", "correct": false, "because": "Unübersichtlichkeit steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die statische Sicht ohne Teilprojekte erstellt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Arbeitspakete reichen"}, {"text": "Nein", "correct": false, "because": "Flexibilität möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt einen Eintrag der statischen Sicht?', 3, '[{"text": "2.3.1 Testskripte erstellen", "correct": true, "because": "Hierarchisch ohne Zeit"}, {"text": "Test bis 15. Mai", "correct": false, "because": "Zeitangabe enthalten"}, {"text": "Irgendwas testen", "correct": false, "because": "Nicht strukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die statische Sicht nur für den Planer relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Beteiligten brauchen sie"}, {"text": "Ja", "correct": false, "because": "Projektweite Bedeutung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale kennzeichnen die statische Sicht?', 4, '[{"text": "Hierarchische Ebenen", "correct": true, "because": "Fördern Struktur"}, {"text": "Zeitliche Abfolge", "correct": false, "because": "Dynamische Sicht"}, {"text": "Nummerierte Einheiten", "correct": true, "because": "Kodierungssystem"}, {"text": "Abgrenzbare Bereiche", "correct": true, "because": "Definieren Teile"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die statische Sicht im PSP dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit essenziell"}, {"text": "Nein", "correct": false, "because": "Dokumentation nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die statische Sicht in der Planung?', 3, '[{"text": "Grundlage für Arbeitspakete", "correct": true, "because": "Strukturiert Aufgaben"}, {"text": "Fortschritt direkt überwachen", "correct": false, "because": "Controlling-Aspekt"}, {"text": "Team direkt einteilen", "correct": false, "because": "Durchführungsaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die statische Sicht ohne Projektziele definiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Ziele geben Orientierung"}, {"text": "Ja", "correct": false, "because": "Unklarheit droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die statische Sicht?', 3, '[{"text": "Unklare Projektanforderungen", "correct": true, "because": "Verhindern Struktur"}, {"text": "Klar definierte Ziele", "correct": false, "because": "Fördern Gliederung"}, {"text": "Gute Kommunikation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die statische Sicht dient der Übersicht. b) Sie zeigt Ressourcen direkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Ressourcen separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der statischen Sicht?', 3, '[{"text": "Strukturierte Projektübersicht", "correct": true, "because": "Fördert Koordination"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Struktur", "correct": false, "because": "Fördert Ordnung"}]');
